 213→#if WITH_DIRECTORY_WATCHER
 214→void UBridgeComponent::OnDirectoryChanged(const TArray<FFileChangeData>& Changes)
 215→{
 216→    for (const FFileChangeData& Change : Changes)
 217→    {
 218→        if (bVerboseLogging)
 219→        {
 220→            BridgeLog(FString::Printf(TEXT("File changed: %s"), *Change.Filename));
 221→        }
 222→
 223→        // State file changes (JSON or USD bridge state)
 224→        if (Change.Filename.EndsWith(TEXT("state.json")) ||
 225→            Change.Filename.EndsWith(TEXT("bridge_state.usda")))
 226→        {
 227→            // Debounce state file changes
 228→            TimeSinceLastStateChange = 0.0f;
 229→            bStateChangePending = true;
 230→        }
 231→        // USD cognitive profile changes (separate from bridge state)
 232→        else if (Change.Filename.EndsWith(TEXT("cognitive_profile.usda")) ||
 233→                 Change.Filename.EndsWith(TEXT("cognitive_substrate.usda")))
 234→        {
 235→            // Debounce USD profile file changes
 236→            TimeSinceLastUsdChange = 0.0f;
 237→            bUsdChangePending = true;
 238→        }
 239→    }
 240→}
 241→#endif
