 332→void UBridgeComponent::HandleQuestionState(const TSharedPtr<FJsonObject>& JsonObj)
 333→{
 334→    // Protocol nests question data under "question" key, but also support flat format
 335→    const TSharedPtr<FJsonObject>* QuestionObjPtr;
 336→    const TSharedPtr<FJsonObject>& QuestionData =
 337→        JsonObj->TryGetObjectField(TEXT("question"), QuestionObjPtr) ? *QuestionObjPtr : JsonObj;
 338→
 339→    // Parse into struct
 340→    CurrentQuestion = FTranslatorsQuestion();
 341→    CurrentQuestion.Index = QuestionData->GetIntegerField(TEXT("index"));
 342→    CurrentQuestion.Total = QuestionData->GetIntegerField(TEXT("total"));
 343→    CurrentQuestion.QuestionId = QuestionData->GetStringField(TEXT("id"));
 344→    CurrentQuestion.Text = QuestionData->GetStringField(TEXT("text"));
 345→    CurrentQuestion.Scene = QuestionData->GetStringField(TEXT("scene"));
 346→
 347→    // Parse options array
 348→    const TArray<TSharedPtr<FJsonValue>>* OptionsArray;
 349→    if (QuestionData->TryGetArrayField(TEXT("options"), OptionsArray))
 350→    {
 351→        for (const TSharedPtr<FJsonValue>& OptionVal : *OptionsArray)
 352→        {
 353→            const TSharedPtr<FJsonObject>& OptionObj = OptionVal->AsObject();
 354→            if (OptionObj.IsValid())
 355→            {
 356→                CurrentQuestion.OptionLabels.Add(OptionObj->GetStringField(TEXT("label")));
 357→                CurrentQuestion.OptionDirections.Add(OptionObj->GetStringField(TEXT("direction")));
 358→            }
 359→        }
 360→    }
 361→
 362→    // Assign depth label based on question index
 363→    CurrentQuestion.DepthLabel = GetDepthLabelForIndex(CurrentQuestion.Index);
 364→
 365→    BridgeLog(FString::Printf(TEXT("Question %d/%d [%s]: %s"),
 366→        CurrentQuestion.Index + 1, CurrentQuestion.Total, *CurrentQuestion.DepthLabel, *CurrentQuestion.QuestionId));
 367→
 368→    // Broadcast raw JSON for flexible handling
 369→    OnQuestionReceived.Broadcast(CurrentStateJson);
 370→}
