 373→void UBridgeComponent::HandleTransitionState(const TSharedPtr<FJsonObject>& JsonObj)
 374→{
 375→    const TSharedPtr<FJsonObject>* TransObjPtr;
 376→    const TSharedPtr<FJsonObject>& TransData =
 377→        JsonObj->TryGetObjectField(TEXT("transition"), TransObjPtr) ? *TransObjPtr : JsonObj;
 378→
 379→    FString Direction = TransData->GetStringField(TEXT("direction"));
 380→    FString NextScene = TransData->GetStringField(TEXT("next_scene"));
 381→    float Progress = TransData->GetNumberField(TEXT("progress"));
 382→
 383→    BridgeLog(FString::Printf(TEXT("Transition: %s -> %s (%.0f%%)"),
 384→        *Direction, *NextScene, Progress * 100.0f));
 385→
 386→    OnTransitionReceived.Broadcast(Direction, NextScene);
 387→}
