 481→// === UTILITY ===
 482→
 483→void UBridgeComponent::WriteJsonToFile(const FString& Filename, const TSharedPtr<FJsonObject>& JsonObj)
 484→{
 485→    FString FilePath = GetBridgeFilePath(Filename);
 486→    FString OutputString;
 487→
 488→    TSharedRef<TJsonWriter<>> Writer = TJsonWriterFactory<>::Create(&OutputString);
 489→    FJsonSerializer::Serialize(JsonObj.ToSharedRef(), Writer);
 490→
 491→    // Write with retry logic (file may be locked by Claude Code reading it)
 492→    int32 MaxRetries = 3;
 493→    for (int32 Retry = 0; Retry < MaxRetries; ++Retry)
 494→    {
 495→        if (FFileHelper::SaveStringToFile(OutputString, *FilePath))
 496→        {
 497→            return; // Success
 498→        }
 499→
 500→        if (Retry < MaxRetries - 1)
 501→        {
 502→            BridgeLog(FString::Printf(TEXT("Write failed, retry %d/%d..."), Retry + 1, MaxRetries));
 503→            FPlatformProcess::Sleep(0.1f);
 504→        }
 505→    }
 506→
 507→    BridgeLog(FString::Printf(TEXT("ERROR: Failed to write %s after %d retries"), *Filename, MaxRetries));
 508→}
