 530→// === USD NATIVE COMMUNICATION (v2.0.0) ===
 531→
 532→bool UBridgeComponent::ProcessBridgeStateUsda()
 533→{
 534→    FString FilePath = GetBridgeFilePath(TEXT("bridge_state.usda"));
 535→    FString Content;
 536→
 537→    if (!FFileHelper::LoadFileToString(Content, *FilePath))
 538→    {
 539→        return false;
 540→    }
 541→
 542→    // Parse sync_status variant
 543→    FString SyncStatus = ParseUsdaVariant(Content, TEXT("sync_status"));
 544→    FString MessageType = ParseUsdaVariant(Content, TEXT("message_type"));
 545→
 546→    if (bVerboseLogging)
 547→    {
 548→        BridgeLog(FString::Printf(TEXT("USD sync_status=%s, message_type=%s"), *SyncStatus, *MessageType));
 549→    }
 550→
 551→    // Route based on message type
 552→    if (MessageType == TEXT("ready"))
 553→    {
 554→        HandleUsdaReadyState(Content);
 555→    }
 556→    else if (MessageType == TEXT("question") && SyncStatus == TEXT("question_pending"))
 557→    {
 558→        HandleUsdaQuestionState(Content);
 559→    }
 560→    else if (MessageType == TEXT("transition"))
 561→    {
 562→        HandleUsdaTransitionState(Content);
 563→    }
 564→    else if (MessageType == TEXT("finale"))
 565→    {
 566→        HandleUsdaFinaleState(Content);
 567→    }
 568→
 569→    return true;
 570→}
