 640→void UBridgeComponent::HandleUsdaReadyState(const FString& Content)
 641→{
 642→    int32 TotalQuestions = FCString::Atoi(*ParseUsdaAttribute(Content, TEXT("Ready"), TEXT("total_questions")));
 643→    FString FirstScene = ParseUsdaAttribute(Content, TEXT("Ready"), TEXT("first_scene"));
 644→
 645→    if (TotalQuestions <= 0) TotalQuestions = 8;
 646→
 647→    BridgeLog(FString::Printf(TEXT("USD Ready: %d questions, first scene: %s"), TotalQuestions, *FirstScene));
 648→
 649→    bIsConnected = true;
 650→    bUsingUsdMode = true;
 651→    OnBridgeReady.Broadcast(TotalQuestions);
 652→}
