 820→
 821→FString UBridgeComponent::UpdateUsdaAttribute(const FString& Content, const FString& PrimName, const FString& AttrName, const FString& NewValue, bool bIsString)
 822→{
 823→    // Find attribute pattern and replace value
 824→    // For string: string attrName = "value"
 825→    // For numeric: int/float/double attrName = value
 826→
 827→    FString Result = Content;
 828→
 829→    if (bIsString)
 830→    {
 831→        // Find: string attrName = "..."
 832→        FString SearchPattern = FString::Printf(TEXT("string %s = \""), *AttrName);
 833→        int32 StartIdx = Result.Find(SearchPattern);
 834→        if (StartIdx != INDEX_NONE)
 835→        {
 836→            StartIdx += SearchPattern.Len();
 837→            int32 EndIdx = Result.Find(TEXT("\""), ESearchCase::CaseSensitive, ESearchDir::FromStart, StartIdx);
 838→            if (EndIdx != INDEX_NONE)
 839→            {
 840→                FString EscapedValue = NewValue.Replace(TEXT("\\"), TEXT("\\\\")).Replace(TEXT("\""), TEXT("\\\""));
 841→                Result = Result.Left(StartIdx) + EscapedValue + Result.Mid(EndIdx);
 842→            }
 843→        }
 844→    }
 845→    else
 846→    {
 847→        // Find numeric attributes: int/float/double attrName = value
 848→        TArray<FString> TypePrefixes = { TEXT("int"), TEXT("float"), TEXT("double"), TEXT("bool") };
 849→
 850→        for (const FString& TypePrefix : TypePrefixes)
 851→        {
 852→            FString SearchPattern = FString::Printf(TEXT("%s %s = "), *TypePrefix, *AttrName);
 853→            int32 StartIdx = Result.Find(SearchPattern);
 854→            if (StartIdx != INDEX_NONE)
 855→            {
 856→                StartIdx += SearchPattern.Len();
 857→                // Find end of value (newline or space or semicolon)
 858→                int32 EndIdx = StartIdx;
 859→                while (EndIdx < Result.Len())
 860→                {
 861→                    TCHAR C = Result[EndIdx];
 862→                    if (C == '\n' || C == '\r' || C == ';' || C == ' ' || C == '\t')
 863→                    {
 864→                        break;
 865→                    }
 866→                    EndIdx++;
 867→                }
 868→                Result = Result.Left(StartIdx) + NewValue + Result.Mid(EndIdx);
 869→                break;
 870→            }
 871→        }
 872→    }
 873→
 874→    return Result;
 875→}
