 877→
 878→void UBridgeComponent::UpdateBehavioralSignals(FString& Content, float ResponseTimeMs)
 879→{
 880→    // ═══════════════════════════════════════════════════════════════════════════════
 881→    // THINKINGMACHINES [He2025] BATCH-INVARIANCE COMPLIANT
 882→    // Same signals → Same routing → Same behavior
 883→    // FIXED thresholds ensure deterministic expert selection regardless of load
 884→    // ═══════════════════════════════════════════════════════════════════════════════
 885→
 886→    // PHASE 1: DETECT - Collect signals
 887→    ResponseTimes.Add(ResponseTimeMs);
 888→
 889→    // Calculate average response time (FIXED algorithm - sum/count)
 890→    float TotalTime = 0.0f;
 891→    for (float Time : ResponseTimes)
 892→    {
 893→        TotalTime += Time;
 894→    }
 895→    float AvgResponseTime = ResponseTimes.Num() > 0 ? TotalTime / ResponseTimes.Num() : 0.0f;
 896→
 897→    // FIXED THRESHOLDS (batch-invariant - same across all sessions)
 898→    const float HESITATION_THRESHOLD_MS = 10000.0f;   // 10 seconds
 899→    const float RAPID_CLICK_THRESHOLD_MS = 500.0f;    // 0.5 seconds
 900→    const float DEPLETED_AVG_THRESHOLD_MS = 15000.0f; // 15 seconds average
 901→    const int32 HESITATION_COUNT_THRESHOLD = 2;
 902→    const int32 RAPID_CLICK_COUNT_THRESHOLD = 3;
 903→
 904→    // Detect hesitation
 905→    bool bLongHesitation = ResponseTimeMs > HESITATION_THRESHOLD_MS;
 906→    if (bLongHesitation)
 907→    {
 908→        HesitationCount++;
 909→    }
 910→
 911→    // Detect rapid clicking
 912→    bool bRapidClick = ResponseTimeMs < RAPID_CLICK_THRESHOLD_MS && ResponseTimes.Num() > 1;
 913→    if (bRapidClick)
 914→    {
 915→        RapidClickCount++;
 916→    }
 917→
 918→    // PHASE 2: CASCADE - ADHD_MoE FIXED PRIORITY ROUTING
 919→    // Priority: Validator(1) > Scaffolder(2) > Restorer(3) > Refocuser(4) > Celebrator(5) > Socratic(6) > Direct(7)
 920→    // First match wins - NEVER skip or reorder
 921→
 922→    FString DetectedState = TEXT("focused");
 923→    FString RecommendedExpert = TEXT("Direct");
 924→    FString BurnoutLevel = TEXT("GREEN");
 925→    FString MomentumPhase = TEXT("rolling");
 926→
 927→    // Priority 1: Validator - frustrated, RED burnout, caps, negative signals
 928→    if (RapidClickCount > RAPID_CLICK_COUNT_THRESHOLD)
 929→    {
 930→        DetectedState = TEXT("frustrated");
 931→        RecommendedExpert = TEXT("Validator");
 932→        BurnoutLevel = TEXT("RED");
 933→        MomentumPhase = TEXT("crashed");
 934→    }
 935→    // Priority 2: Scaffolder - overwhelmed, stuck, too_many signals
 936→    else if (bLongHesitation || HesitationCount > HESITATION_COUNT_THRESHOLD)
 937→    {
 938→        DetectedState = TEXT("stuck");
 939→        RecommendedExpert = TEXT("Scaffolder");
 940→        BurnoutLevel = TEXT("ORANGE");
 941→        MomentumPhase = TEXT("declining");
 942→    }
 943→    // Priority 3: Restorer - depleted, ORANGE burnout, post-crash
 944→    else if (AvgResponseTime > DEPLETED_AVG_THRESHOLD_MS)
 945→    {
 946→        DetectedState = TEXT("depleted");
 947→        RecommendedExpert = TEXT("Restorer");
 948→        BurnoutLevel = TEXT("ORANGE");
 949→        MomentumPhase = TEXT("crashed");
 950→    }
 951→    // Priority 4: Refocuser - distracted, tangent signals
 952→    else if (ResponseTimes.Num() > 3 && ResponseTimeMs > AvgResponseTime * 2.0f)
 953→    {
 954→        DetectedState = TEXT("distracted");
 955→        RecommendedExpert = TEXT("Refocuser");
 956→        BurnoutLevel = TEXT("YELLOW");
 957→        MomentumPhase = TEXT("declining");
 958→    }
 959→    // Priority 5: Celebrator - task_complete, milestone reached
 960→    else if (CurrentQuestion.Index == CurrentQuestion.Total - 1)
 961→    {
 962→        DetectedState = TEXT("completing");
 963→        RecommendedExpert = TEXT("Celebrator");
 964→        BurnoutLevel = TEXT("GREEN");
 965→        MomentumPhase = TEXT("peak");
 966→    }
 967→    // Priority 6: Socratic - exploring, high energy, "what if" signals
 968→    else if (ResponseTimes.Num() >= 2 && ResponseTimeMs > 3000.0f && ResponseTimeMs < 8000.0f)
 969→    {
 970→        DetectedState = TEXT("exploring");
 971→        RecommendedExpert = TEXT("Socratic");
 972→        BurnoutLevel = TEXT("GREEN");
 973→        MomentumPhase = TEXT("building");
 974→    }
 975→    // Priority 7: Direct - focused, hyperfocused, flow state (DEFAULT)
 976→    else
 977→    {
 978→        DetectedState = TEXT("focused");
 979→        RecommendedExpert = TEXT("Direct");
 980→        BurnoutLevel = TEXT("GREEN");
 981→        MomentumPhase = (ResponseTimes.Num() > 5) ? TEXT("rolling") : TEXT("building");
 982→    }
 983→
 984→    // PHASE 3: LOCK - Parameters locked for this response (no further changes)
 985→
 986→    // PHASE 4: EXECUTE - Update signals in USD content
 987→    Content = UpdateUsdaAttribute(Content, TEXT("BehavioralSignals"), TEXT("last_response_time_ms"), FString::SanitizeFloat(ResponseTimeMs), false);
 988→    Content = UpdateUsdaAttribute(Content, TEXT("BehavioralSignals"), TEXT("average_response_time_ms"), FString::SanitizeFloat(AvgResponseTime), false);
 989→    Content = UpdateUsdaAttribute(Content, TEXT("BehavioralSignals"), TEXT("hesitation_count"), FString::FromInt(HesitationCount), false);
 990→    Content = UpdateUsdaAttribute(Content, TEXT("BehavioralSignals"), TEXT("long_hesitation_detected"), bLongHesitation ? TEXT("true") : TEXT("false"), false);
 991→    Content = UpdateUsdaAttribute(Content, TEXT("BehavioralSignals"), TEXT("rapid_click_count"), FString::FromInt(RapidClickCount), false);
 992→    Content = UpdateUsdaAttribute(Content, TEXT("BehavioralSignals"), TEXT("detected_state"), DetectedState, true);
 993→    Content = UpdateUsdaAttribute(Content, TEXT("BehavioralSignals"), TEXT("recommended_expert"), RecommendedExpert, true);
 994→    Content = UpdateUsdaAttribute(Content, TEXT("BehavioralSignals"), TEXT("burnout_level"), BurnoutLevel, true);
 995→    Content = UpdateUsdaAttribute(Content, TEXT("BehavioralSignals"), TEXT("momentum_phase"), MomentumPhase, true);
 996→
 997→    // PHASE 5: UPDATE - Log routing decision for traceability
 998→    if (bVerboseLogging)
 999→    {
1000→        BridgeLog(FString::Printf(TEXT("[EXEC] State=%s Expert=%s Burnout=%s Momentum=%s"),
1001→            *DetectedState, *RecommendedExpert, *BurnoutLevel, *MomentumPhase));
1002→    }
1003→}
