1058→// === COGNITIVE PROFILE PARSING ===
1059→
1060→FTranslatorsProfile UBridgeComponent::ParseCognitiveProfile(const FString& UsdPath)
1061→{
1062→    FTranslatorsProfile Profile;
1063→
1064→    FString Content;
1065→    if (!FFileHelper::LoadFileToString(Content, *UsdPath))
1066→    {
1067→        BridgeLog(FString::Printf(TEXT("Could not read profile: %s"), *UsdPath));
1068→        return Profile;
1069→    }
1070→
1071→    BridgeLog(FString::Printf(TEXT("Parsing cognitive profile from: %s"), *UsdPath));
1072→
1073→    // Parse checksum
1074→    {
1075→        FRegexPattern Pattern(TEXT("string checksum = \"([^\"]*)\""));
1076→        FRegexMatcher Matcher(Pattern, Content);
1077→        if (Matcher.FindNext())
1078→        {
1079→            Profile.Checksum = Matcher.GetCaptureGroup(1);
1080→        }
1081→    }
1082→
1083→    // Parse anchor
1084→    {
1085→        FRegexPattern Pattern(TEXT("string anchor = \"([^\"]*)\""));
1086→        FRegexMatcher Matcher(Pattern, Content);
1087→        if (Matcher.FindNext())
1088→        {
1089→            Profile.Anchor = Matcher.GetCaptureGroup(1);
1090→        }
1091→    }
1092→
1093→    // Parse anchor from customData
1094→    {
1095→        FRegexPattern Pattern(TEXT("string translators_anchor = \"([^\"]*)\""));
1096→        FRegexMatcher Matcher(Pattern, Content);
1097→        if (Matcher.FindNext())
1098→        {
1099→            Profile.Anchor = Matcher.GetCaptureGroup(1);
1100→        }
1101→    }
1102→
1103→    // Parse Profile dimensions (float cognitive_density = 0.5)
1104→    // and Traits labels (string load = "adaptive")
1105→    // Combine them into FTranslatorsTrait entries
1106→    TMap<FString, float> DimensionScores;
1107→    TMap<FString, FString> TraitLabels;
1108→
1109→    // Extract Profile section: float <name> = <value>
1110→    {
1111→        int32 ProfileStart = Content.Find(TEXT("def Xform \"Profile\""));
1112→        if (ProfileStart != INDEX_NONE)
1113→        {
1114→            int32 BlockStart = Content.Find(TEXT("{"), ESearchCase::CaseSensitive, ESearchDir::FromStart, ProfileStart);
1115→            if (BlockStart != INDEX_NONE)
1116→            {
1117→                int32 BraceDepth = 1;
1118→                int32 BlockEnd = BlockStart + 1;
1119→                while (BlockEnd < Content.Len() && BraceDepth > 0)
1120→                {
1121→                    if (Content[BlockEnd] == TEXT('{')) BraceDepth++;
1122→                    else if (Content[BlockEnd] == TEXT('}')) BraceDepth--;
1123→                    BlockEnd++;
1124→                }
1125→
1126→                FString ProfileBlock = Content.Mid(BlockStart, BlockEnd - BlockStart);
1127→                FRegexPattern Pattern(TEXT("float (\\w+) = ([\\d.]+)"));
1128→                FRegexMatcher Matcher(Pattern, ProfileBlock);
1129→                while (Matcher.FindNext())
1130→                {
1131→                    FString Name = Matcher.GetCaptureGroup(1);
1132→                    float Value = FCString::Atof(*Matcher.GetCaptureGroup(2));
1133→                    DimensionScores.Add(Name, Value);
1134→                }
1135→            }
1136→        }
1137→    }
1138→
1139→    // Extract Traits section: string <question_id> = "<trait_label>"
1140→    // These are inside def Xform "Traits" { ... }
1141→    {
1142→        // Find the Traits block
1143→        int32 TraitsStart = Content.Find(TEXT("def Xform \"Traits\""));
1144→        if (TraitsStart != INDEX_NONE)
1145→        {
1146→            // Find the closing brace for this block
1147→            int32 BlockStart = Content.Find(TEXT("{"), ESearchCase::CaseSensitive, ESearchDir::FromStart, TraitsStart);
1148→            if (BlockStart != INDEX_NONE)
1149→            {
1150→                int32 BraceDepth = 1;
1151→                int32 BlockEnd = BlockStart + 1;
1152→                while (BlockEnd < Content.Len() && BraceDepth > 0)
1153→                {
1154→                    if (Content[BlockEnd] == TEXT('{')) BraceDepth++;
1155→                    else if (Content[BlockEnd] == TEXT('}')) BraceDepth--;
1156→                    BlockEnd++;
1157→                }
1158→
1159→                FString TraitsBlock = Content.Mid(BlockStart, BlockEnd - BlockStart);
1160→                FRegexPattern Pattern(TEXT("string (\\w+) = \"([^\"]*)\""));
1161→                FRegexMatcher Matcher(Pattern, TraitsBlock);
1162→                while (Matcher.FindNext())
1163→                {
1164→                    TraitLabels.Add(Matcher.GetCaptureGroup(1), Matcher.GetCaptureGroup(2));
1165→                }
1166→            }
1167→        }
1168→    }
1169→
1170→    // Map between question IDs and dimension names
1171→    // Question IDs: load, pace, uncertainty, feedback, recovery, starting, completion, essence
1172→    // Dimension names: cognitive_density, processing_pace, uncertainty_tolerance, feedback_style,
1173→    //                  home_altitude, guidance_frequency, default_paradigm, tangent_tolerance
1174→    TMap<FString, FString> QuestionToDimension;
1175→    QuestionToDimension.Add(TEXT("load"), TEXT("cognitive_density"));
1176→    QuestionToDimension.Add(TEXT("pace"), TEXT("processing_pace"));
1177→    QuestionToDimension.Add(TEXT("uncertainty"), TEXT("uncertainty_tolerance"));
1178→    QuestionToDimension.Add(TEXT("feedback"), TEXT("feedback_style"));
1179→    QuestionToDimension.Add(TEXT("recovery"), TEXT("home_altitude"));
1180→    QuestionToDimension.Add(TEXT("starting"), TEXT("guidance_frequency"));
1181→    QuestionToDimension.Add(TEXT("completion"), TEXT("default_paradigm"));
1182→    QuestionToDimension.Add(TEXT("essence"), TEXT("tangent_tolerance"));
1183→
1184→    // Build traits from combined data
1185→    for (const auto& Pair : TraitLabels)
1186→    {
1187→        FTranslatorsTrait Trait;
1188→        Trait.Label = Pair.Value;
1189→
1190→        // Find matching dimension
1191→        FString* DimName = QuestionToDimension.Find(Pair.Key);
1192→        if (DimName)
1193→        {
1194→            Trait.Dimension = *DimName;
1195→            float* Score = DimensionScores.Find(*DimName);
1196→            Trait.Score = Score ? *Score : 0.5f;
1197→        }
1198→        else
1199→        {
1200→            Trait.Dimension = Pair.Key;
1201→            Trait.Score = 0.5f;
1202→        }
1203→
1204→        // Generate behavior description from score
1205→        if (Trait.Score >= 0.7f)
1206→        {
1207→            Trait.Behavior = FString::Printf(TEXT("Strong %s tendency"), *Trait.Label);
1208→        }
1209→        else if (Trait.Score <= 0.3f)
1210→        {
1211→            Trait.Behavior = FString::Printf(TEXT("Measured %s approach"), *Trait.Label);
1212→        }
1213→        else
1214→        {
1215→            Trait.Behavior = FString::Printf(TEXT("Balanced %s style"), *Trait.Label);
1216→        }
1217→
1218→        Profile.Traits.Add(Trait);
1219→    }
1220→
1221→    // Generate insights from the profile data
1222→    // (The USDA doesn't contain explicit insights, so derive them from scores)
1223→    for (const FTranslatorsTrait& Trait : Profile.Traits)
1224→    {
1225→        if (Trait.Score >= 0.7f)
1226→        {
1227→            Profile.Insights.Add(FString::Printf(TEXT("High %s (%s) suggests strong preference in this dimension"),
1228→                *Trait.Dimension.Replace(TEXT("_"), TEXT(" ")), *Trait.Label));
1229→        }
1230→        else if (Trait.Score <= 0.3f)
1231→        {
1232→            Profile.Insights.Add(FString::Printf(TEXT("Low %s (%s) indicates a focused approach here"),
1233→                *Trait.Dimension.Replace(TEXT("_"), TEXT(" ")), *Trait.Label));
1234→        }
1235→    }
1236→
1237→    BridgeLog(FString::Printf(TEXT("Parsed profile: %d traits, %d insights, checksum=%s"),
1238→        Profile.Traits.Num(), Profile.Insights.Num(), *Profile.Checksum));
1239→
1240→    return Profile;
1241→}
