163→void UW_QuestionDisplay::ShowQuestion(const FTranslatorsQuestion& Question)
164→{
165→    CurrentQuestion = Question;
166→    SelectedOptionIndex = -1;
167→
168→    // Update depth label with tier-specific color
169→    if (DepthText)
170→    {
171→        DepthText->SetText(FText::FromString(Question.DepthLabel));
172→
173→        // Color by tier
174→        FLinearColor TierColor;
175→        if (Question.DepthLabel == TEXT("SURFACE"))
176→        {
177→            TierColor = FLinearColor(0.5f, 0.8f, 0.5f, 1.0f);  // Sage green
178→        }
179→        else if (Question.DepthLabel == TEXT("PATTERNS"))
180→        {
181→            TierColor = FLinearColor(0.3f, 0.8f, 0.8f, 1.0f);  // Teal
182→        }
183→        else if (Question.DepthLabel == TEXT("FEELINGS"))
184→        {
185→            TierColor = FLinearColor(1.0f, 0.5f, 0.45f, 1.0f);  // Coral
186→        }
187→        else // CORE
188→        {
189→            TierColor = FLinearColor(1.0f, 0.85f, 0.3f, 1.0f);  // Gold
190→        }
191→        DepthText->SetColorAndOpacity(FSlateColor(TierColor));
192→    }
193→
194→    // Update question text
195→    if (QuestionText)
196→    {
197→        FString FormattedText = Question.Text.Replace(TEXT("\\n"), TEXT("\n"));
198→        QuestionText->SetText(FText::FromString(FormattedText));
199→    }
200→
201→    // Update progress
202→    UpdateProgress(Question.Index + 1, Question.Total);
203→
204→    // Create option buttons
205→    CreateOptionButtons();
206→
207→    UE_LOG(LogTemp, Log, TEXT("[W_QuestionDisplay] Showing question %d/%d: %s"),
208→        Question.Index + 1, Question.Total, *Question.QuestionId);
209→}
