243→void UW_QuestionDisplay::CreateOptionButtons()
244→{
245→    ClearOptions();
246→
247→    if (!OptionsContainer)
248→    {
249→        UE_LOG(LogTemp, Warning, TEXT("[W_QuestionDisplay] No OptionsContainer"));
250→        return;
251→    }
252→
253→    TSubclassOf<UW_OptionButton> ButtonClass = OptionButtonClass;
254→    if (!ButtonClass)
255→    {
256→        ButtonClass = UW_OptionButton::StaticClass();
257→    }
258→
259→    const int32 NumOptions = CurrentQuestion.OptionLabels.Num();
260→    for (int32 i = 0; i < NumOptions; i++)
261→    {
262→        UW_OptionButton* NewButton = CreateWidget<UW_OptionButton>(this, ButtonClass);
263→        if (NewButton)
264→        {
265→            FText Label = FText::FromString(CurrentQuestion.OptionLabels[i]);
266→            FString Dir = CurrentQuestion.OptionDirections.IsValidIndex(i)
267→                ? CurrentQuestion.OptionDirections[i]
268→                : TEXT("forward");
269→
270→            NewButton->SetupOption(i, Label, Dir);
271→            NewButton->OnOptionClicked.AddDynamic(this, &UW_QuestionDisplay::HandleOptionClicked);
272→
273→            UVerticalBoxSlot* ButtonSlot = OptionsContainer->AddChildToVerticalBox(NewButton);
274→            if (ButtonSlot)
275→            {
276→                ButtonSlot->SetPadding(FMargin(0.0f, 8.0f, 0.0f, 8.0f));
277→                ButtonSlot->SetHorizontalAlignment(HAlign_Fill);
278→            }
279→
280→            OptionButtons.Add(NewButton);
281→        }
282→    }
