158→void UW_OptionButton::BuildWidgetTree()
159→{
160→    // Create border as root (for background color)
161→    ButtonBorder = WidgetTree->ConstructWidget<UBorder>(UBorder::StaticClass(), TEXT("ButtonBorder"));
162→    ButtonBorder->SetBrushColor(NormalColor);
163→    ButtonBorder->SetPadding(FMargin(20.0f, 12.0f));
164→    WidgetTree->RootWidget = ButtonBorder;
165→
166→    // Create size box to ensure consistent button size
167→    USizeBox* ButtonSizeBox = WidgetTree->ConstructWidget<USizeBox>(USizeBox::StaticClass(), TEXT("ButtonSizeBox"));
168→    ButtonSizeBox->SetMinDesiredWidth(400.0f);
169→    ButtonSizeBox->SetMinDesiredHeight(50.0f);
170→    ButtonBorder->AddChild(ButtonSizeBox);
171→
172→    // Create the actual button (invisible, just for interaction)
173→    OptionButton = WidgetTree->ConstructWidget<UButton>(UButton::StaticClass(), TEXT("OptionButton"));
174→
175→    // Make button transparent - border handles visuals
176→    FButtonStyle TransparentStyle;
177→    TransparentStyle.Normal.TintColor = FSlateColor(FLinearColor::Transparent);
178→    TransparentStyle.Hovered.TintColor = FSlateColor(FLinearColor::Transparent);
179→    TransparentStyle.Pressed.TintColor = FSlateColor(FLinearColor::Transparent);
180→    OptionButton->SetStyle(TransparentStyle);
181→
182→    ButtonSizeBox->AddChild(OptionButton);
183→
184→    // Create label text
185→    OptionLabel = WidgetTree->ConstructWidget<UTextBlock>(UTextBlock::StaticClass(), TEXT("OptionLabel"));
186→    OptionLabel->SetText(LabelText.IsEmpty() ? FText::FromString(TEXT("Option")) : LabelText);
187→    OptionLabel->SetColorAndOpacity(FSlateColor(TextColor));
188→    OptionLabel->SetJustification(ETextJustify::Center);
189→    OptionLabel->SetAutoWrapText(true);
190→
191→    OptionLabel->SetFont(FSlateFontInfo(FPaths::EngineContentDir() / TEXT("Slate/Fonts/Roboto-Regular.ttf"), 18));
192→
193→    OptionButton->AddChild(OptionLabel);
194→
195→    UE_LOG(LogTemp, Log, TEXT("[W_OptionButton] Built programmatic widget tree"));
196→}
