113→    BackgroundBorder = WidgetTree->ConstructWidget<UBorder>(UBorder::StaticClass(), TEXT("BackgroundBorder"));
114→    BackgroundBorder->SetBrushColor(BackgroundColor);
115→    BackgroundBorder->SetHorizontalAlignment(HAlign_Center);
116→    BackgroundBorder->SetVerticalAlignment(VAlign_Center);
