119→
120→    // Content box (centered by border alignment)
121→    UVerticalBox* ContentBox = WidgetTree->ConstructWidget<UVerticalBox>(UVerticalBox::StaticClass(), TEXT("ContentBox"));
122→    BackgroundBorder->AddChild(ContentBox);
123→
124→    // === Title: "The Translators" ===
125→    TitleText = WidgetTree->ConstructWidget<UTextBlock>(UTextBlock::StaticClass(), TEXT("TitleText"));
126→    TitleText->SetText(FText::FromString(TEXT("The Translators")));
127→    TitleText->SetColorAndOpacity(FSlateColor(TitleColor));
128→    TitleText->SetJustification(ETextJustify::Center);
129→    TitleText->SetFont(MakeFont(56));
130→
131→    UVerticalBoxSlot* TitleSlot = ContentBox->AddChildToVerticalBox(TitleText);
132→    if (TitleSlot)
133→    {
134→        TitleSlot->SetPadding(FMargin(0.0f, 0.0f, 0.0f, 12.0f));
135→        TitleSlot->SetHorizontalAlignment(HAlign_Center);
136→    }
137→
138→    // === Subtitle: "A cognitive profiling experience" ===
139→    SubtitleText = WidgetTree->ConstructWidget<UTextBlock>(UTextBlock::StaticClass(), TEXT("SubtitleText"));
140→    SubtitleText->SetText(FText::FromString(TEXT("A cognitive profiling experience")));
141→    SubtitleText->SetColorAndOpacity(FSlateColor(SubtitleColor));
142→    SubtitleText->SetJustification(ETextJustify::Center);
143→    SubtitleText->SetFont(MakeFont(18));
144→
145→    UVerticalBoxSlot* SubtitleSlot = ContentBox->AddChildToVerticalBox(SubtitleText);
146→    if (SubtitleSlot)
147→    {
148→        SubtitleSlot->SetPadding(FMargin(0.0f, 0.0f, 0.0f, 60.0f));
149→        SubtitleSlot->SetHorizontalAlignment(HAlign_Center);
150→    }
151→
152→    // === Prompt: "Press ENTER to begin" ===
153→    PromptText = WidgetTree->ConstructWidget<UTextBlock>(UTextBlock::StaticClass(), TEXT("PromptText"));
154→    PromptText->SetText(FText::FromString(TEXT("Press ENTER to begin")));
155→    PromptText->SetColorAndOpacity(FSlateColor(PromptColor));
156→    PromptText->SetJustification(ETextJustify::Center);
157→    PromptText->SetFont(MakeFont(16));
158→
159→    UVerticalBoxSlot* PromptSlot = ContentBox->AddChildToVerticalBox(PromptText);
160→    if (PromptSlot)
161→    {
162→        PromptSlot->SetHorizontalAlignment(HAlign_Center);
163→    }
164→
165→    UE_LOG(LogTemp, Log, TEXT("[W_TitleScreen] Built programmatic widget tree (Border root)"));
166→}
