102→void UW_FinaleScreen::DisplayProfile(const FTranslatorsProfile& Profile)
103→{
104→    if (!Profile.IsValid())
105→    {
106→        UE_LOG(LogTemp, Warning, TEXT("[W_FinaleScreen] Empty profile - nothing to display"));
107→        return;
108→    }
109→
110→    // Populate traits
111→    if (TraitsContainer)
112→    {
113→        TraitsContainer->ClearChildren();
114→
115→        for (const FTranslatorsTrait& Trait : Profile.Traits)
116→        {
117→            // Create a horizontal row: dimension | label | score bar | behavior
118→            UHorizontalBox* Row = NewObject<UHorizontalBox>(this);
119→
120→            // Dimension name (dim color, left-aligned)
121→            UTextBlock* DimText = NewObject<UTextBlock>(this);
122→            FString CleanDim = Trait.Dimension.Replace(TEXT("_"), TEXT(" "));
123→            DimText->SetText(FText::FromString(CleanDim));
124→            DimText->SetColorAndOpacity(FSlateColor(DimColor));
125→            DimText->SetFont(MakeFont(12));
126→
127→            UHorizontalBoxSlot* DimSlot = Row->AddChildToHorizontalBox(DimText);
128→            if (DimSlot)
129→            {
130→                DimSlot->SetPadding(FMargin(0.0f, 0.0f, 16.0f, 0.0f));
131→                DimSlot->SetSize(FSlateChildSize(ESlateSizeRule::Fill));
132→            }
133→
134→            // Label (cyan, bold-ish)
135→            UTextBlock* LabelText = NewObject<UTextBlock>(this);
136→            LabelText->SetText(FText::FromString(Trait.Label));
137→            LabelText->SetColorAndOpacity(FSlateColor(TraitLabelColor));
138→            LabelText->SetFont(MakeFont(14));
139→
140→            UHorizontalBoxSlot* LabelSlot = Row->AddChildToHorizontalBox(LabelText);
141→            if (LabelSlot)
142→            {
143→                LabelSlot->SetPadding(FMargin(0.0f, 0.0f, 16.0f, 0.0f));
144→                LabelSlot->SetSize(FSlateChildSize(ESlateSizeRule::Automatic));
145→            }
146→
147→            // Score (numeric)
148→            UTextBlock* ScoreText = NewObject<UTextBlock>(this);
149→            FString ScoreStr = FString::Printf(TEXT("%.0f%%"), Trait.Score * 100.0f);
150→            ScoreText->SetText(FText::FromString(ScoreStr));
151→            ScoreText->SetColorAndOpacity(FSlateColor(TraitValueColor));
152→            ScoreText->SetFont(MakeFont(12));
153→
154→            UHorizontalBoxSlot* ScoreSlot = Row->AddChildToHorizontalBox(ScoreText);
155→            if (ScoreSlot)
156→            {
157→                ScoreSlot->SetSize(FSlateChildSize(ESlateSizeRule::Automatic));
158→            }
159→
160→            UVerticalBoxSlot* RowSlot = TraitsContainer->AddChildToVerticalBox(Row);
161→            if (RowSlot)
162→            {
163→                RowSlot->SetPadding(FMargin(0.0f, 4.0f, 0.0f, 4.0f));
164→            }
165→
166→            // Behavior description (below the row, if present)
167→            if (!Trait.Behavior.IsEmpty())
168→            {
169→                UTextBlock* BehaviorText = NewObject<UTextBlock>(this);
170→                BehaviorText->SetText(FText::FromString(Trait.Behavior));
171→                BehaviorText->SetColorAndOpacity(FSlateColor(SubtitleColor));
172→                BehaviorText->SetAutoWrapText(true);
173→                BehaviorText->SetFont(MakeFont(11));
174→
175→                UVerticalBoxSlot* BehaviorSlot = TraitsContainer->AddChildToVerticalBox(BehaviorText);
176→                if (BehaviorSlot)
177→                {
178→                    BehaviorSlot->SetPadding(FMargin(20.0f, 0.0f, 0.0f, 8.0f));
179→                }
180→            }
181→        }
182→    }
183→
184→    // Populate insights
185→    if (InsightsContainer)
