202→            }
203→        }
204→    }
205→
206→    // Checksum/anchor
207→    if (ChecksumText)
208→    {
209→        FString ChecksumDisplay;
210→        if (!Profile.Anchor.IsEmpty())
211→        {
212→            ChecksumDisplay = Profile.Anchor;
213→        }
214→        else if (!Profile.Checksum.IsEmpty())
215→        {
216→            ChecksumDisplay = FString::Printf(TEXT("[TRANSLATORS:%s]"), *Profile.Checksum);
