 94→UBridgeComponent* ATranslatorsHUD::FindBridgeComponent()
 95→{
 96→    TArray<AActor*> AllActors;
 97→    UGameplayStatics::GetAllActorsOfClass(GetWorld(), AActor::StaticClass(), AllActors);
 98→
 99→    for (AActor* Actor : AllActors)
100→    {
101→        UBridgeComponent* Bridge = Actor->FindComponentByClass<UBridgeComponent>();
102→        if (Bridge)
103→        {
104→            return Bridge;
105→        }
106→    }
107→
108→    // Fallback: spawn a dedicated actor with BridgeComponent
109→    UE_LOG(LogTemp, Log, TEXT("[TranslatorsHUD] No BridgeComponent found - spawning BridgeActor"));
110→    UWorld* World = GetWorld();
111→    if (World)
112→    {
113→        FActorSpawnParameters SpawnParams;
114→        SpawnParams.SpawnCollisionHandlingOverride = ESpawnActorCollisionHandlingMethod::AlwaysSpawn;
115→        AActor* BridgeActor = World->SpawnActor<AActor>(AActor::StaticClass(), FVector::ZeroVector, FRotator::ZeroRotator, SpawnParams);
116→        if (BridgeActor)
117→        {
118→            UBridgeComponent* Bridge = NewObject<UBridgeComponent>(BridgeActor, TEXT("BridgeComponent"));
119→            Bridge->bVerboseLogging = true;
120→            BridgeActor->AddInstanceComponent(Bridge);
121→            Bridge->RegisterComponent();
122→            return Bridge;
123→        }
124→    }
125→
126→    return nullptr;
127→}
