 72→void UW_ProgressIndicator::UpdateProgress(int32 QuestionsCompleted)
 73→{
 74→    CurrentQuestion = FMath::Clamp(QuestionsCompleted, 0, TotalQuestions);
 75→    RefreshIndicators();
 76→
 77→    UE_LOG(LogTemp, Log, TEXT("[W_ProgressIndicator] Progress: %d/%d (%.0f%%)"),
 78→        CurrentQuestion, TotalQuestions, GetCompletionPercent() * 100.0f);
 79→}
