122→
123→void UW_ProgressIndicator::RefreshIndicators()
124→{
125→    // Update indicator colors
126→    for (int32 i = 0; i < IndicatorImages.Num(); i++)
127→    {
128→        UImage* Indicator = IndicatorImages[i];
129→        if (!Indicator) continue;
130→
131→        FLinearColor Color;
132→        if (i < CurrentQuestion)
133→        {
134→            // Completed
135→            Color = CompletedColor;
136→        }
137→        else if (i == CurrentQuestion)
138→        {
139→            // Current (in progress)
140→            Color = CurrentColor;
141→        }
142→        else
143→        {
144→            // Not yet reached
145→            Color = IncompleteColor;
146→        }
147→
148→        Indicator->SetColorAndOpacity(Color);
149→    }
150→
151→    // Update text label
152→    if (ProgressLabel)
153→    {
154→        FString LabelText = FString::Printf(TEXT("%d / %d"), CurrentQuestion, TotalQuestions);
155→        ProgressLabel->SetText(FText::FromString(LabelText));
156→    }
157→}
