160→void UW_ProgressIndicator::BuildWidgetTree()
161→{
162→    // Create root canvas
163→    UCanvasPanel* RootCanvas = WidgetTree->ConstructWidget<UCanvasPanel>(UCanvasPanel::StaticClass(), TEXT("RootCanvas"));
164→    WidgetTree->RootWidget = RootCanvas;
165→
166→    // Create horizontal container for indicators
167→    IndicatorContainer = WidgetTree->ConstructWidget<UHorizontalBox>(UHorizontalBox::StaticClass(), TEXT("IndicatorContainer"));
168→
169→    UCanvasPanelSlot* ContainerSlot = RootCanvas->AddChildToCanvas(IndicatorContainer);
170→    if (ContainerSlot)
171→    {
172→        ContainerSlot->SetAnchors(FAnchors(0.5f, 0.5f, 0.5f, 0.5f));
173→        ContainerSlot->SetAlignment(FVector2D(0.5f, 0.5f));
174→        ContainerSlot->SetAutoSize(true);
175→    }
176→
177→    UE_LOG(LogTemp, Log, TEXT("[W_ProgressIndicator] Built programmatic widget tree"));
178→}
